  "{count} 项共同评测 · {support}": {"other": "{count} 项共同评测 · {support}"},
  "双方共同拥有当前榜单 {weight} 的名义票权。下表展示各项评测采用的成绩，已知误差的软化处理会影响净支持，不只数赢了几项。": "双方共同拥有当前榜单 {weight} 的名义票权。下表展示各项评测采用的成绩，已知误差的软化处理会影响净支持，不只数赢了几项。",
