  "先确认，是同一个模型": "先确认，是同一个模型",
  "统一各家榜单的名称和版本。同一模型的不同推理档位只选一个代表配置，选择规则预先确定，不挑最高分。匿名测试代号和混用其他模型完成任务的成绩排除；已正式公开的 Preview 版本可以参加。": "统一各家榜单的名称和版本。同一模型的不同推理档位只选一个代表配置，选择规则预先确定，不挑最高分。匿名测试代号和混用其他模型完成任务的成绩排除；已正式公开的 Preview 版本可以参加。",
  "让真正测过的模型相互比较": "让真正测过的模型相互比较",
  "只比较同一评测中的真实成绩。双方都有公开误差时，误差范围内的微小差异更接近平局，不当成确定胜负。没有测到，就没有这一场比较。": "只比较同一评测中的真实成绩。双方都有公开误差时，误差范围内的微小差异更接近平局，不当成确定胜负。没有测到，就没有这一场比较。",
  "先定票权，再汇总共同意见": "先定票权，再汇总共同意见",
  "每项评测使用预先确定的预算。综合榜至少要求三家评测机构、三个证据家族与三个专项覆盖；同一来源重复抓取或展示切片，不会凭空增加票权。": "每项评测使用预先确定的预算。综合榜至少要求三家评测机构、三个证据家族与三个专项覆盖；同一来源重复抓取或展示切片，不会凭空增加票权。",
  "寻找冲突最少的完整排名": "寻找冲突最少的完整排名",
  "不同评测的意见可能冲突。我们选择违背共同证据净票权最少的一条顺序，再单独计算展示指数。缺测不补零分，也不猜测未公开的成绩。": "不同评测的意见可能冲突。我们选择违背共同证据净票权最少的一条顺序，再单独计算展示指数。缺测不补零分，也不猜测未公开的成绩。",
  "为什么有的模型证据较少，也能上榜？": "为什么有的模型证据较少，也能上榜？",
  "评测数量与能力是两件事。综合榜至少需要三家机构与跨能力证据。多数分类要求两家机构，知识采用同一机构的两项评测并明确说明。缺测不记零分，但仍可能造成偏差。": "评测数量与能力是两件事。综合榜至少需要三家机构与跨能力证据。多数分类要求两家机构，知识采用同一机构的两项评测并明确说明。缺测不记零分，但仍可能造成偏差。",
  "“证据敏感”是什么意思？": "“证据敏感”是什么意思？",
  "删去一项评测或一家机构、将单项权重上下调整 20%、或改变误差处理后，名次范围达到三名或以上、某些情景失去参评资格，或有对照未完成，就会提示证据敏感。详情页的情景范围不是 95% 置信区间，不包含未知成绩。": "删去一项评测或一家机构、将单项权重上下调整 20%、或改变误差处理后，名次范围达到三名或以上、某些情景失去参评资格，或有对照未完成，就会提示证据敏感。详情页的情景范围不是 95% 置信区间，不包含未知成绩。",
  "前面的模型一定在两两比较中获胜吗？": "前面的模型一定在两两比较中获胜吗？",
  "不一定。A 可能胜 B，B 胜 C，C 又胜 A。完整榜单要权衡这些冲突；非相邻名次可能与单独比较不同。数学最优表示按当前规则的总冲突最少，不表示已证明所有真实工作中的能力顺序。": "不一定。A 可能胜 B，B 胜 C，C 又胜 A。完整榜单要权衡这些冲突；非相邻名次可能与单独比较不同。数学最优表示按当前规则的总冲突最少，不表示已证明所有真实工作中的能力顺序。",
  "为什么排名可能和我的体验不同？": "为什么排名可能和我的体验不同？",
  "榜单汇集公开评测，反映这些证据支持的综合能力。实际体验还受产品版本、推理档位、工具环境和长任务稳定性影响。我们会用新评测检验旧排名；分数接近时，不应把一两名之差理解成明显强弱。": "榜单汇集公开评测，反映这些证据支持的综合能力。实际体验还受产品版本、推理档位、工具环境和长任务稳定性影响。我们会用新评测检验旧排名；分数接近时，不应把一两名之差理解成明显强弱。",
  "新模型什么时候会出现？": "新模型什么时候会出现？",
  "{site} 每天检查四次上游结果。只有评测方实际发布了新模型的成绩，才能用于排名；网页刷新、价格更新或我们的抓取时间，都不算重新评测。": "{site} 每天检查四次上游结果。只有评测方实际发布了新模型的成绩，才能用于排名；网页刷新、价格更新或我们的抓取时间，都不算重新评测。",
  "某家榜单暂时打不开，会怎样？": "某家榜单暂时打不开，会怎样？",
  "仍有效的来源快照可继续使用。相同评测版本内，临时漏行最多沿用最近七天已核验的记录；仍在公开榜中保留的有效成绩，不因数值长期不变被删除。官方撤回、更正、换版会相应失效或替换，不保留历史最高分。整轮计算失败时保留上一轮有效榜及原时间。": "仍有效的来源快照可继续使用。相同评测版本内，临时漏行最多沿用最近七天已核验的记录；仍在公开榜中保留的有效成绩，不因数值长期不变被删除。官方撤回、更正、换版会相应失效或替换，不保留历史最高分。整轮计算失败时保留上一轮有效榜及原时间。",
  "综合指数会和专项评测重复计分吗？": "综合指数会和专项评测重复计分吗？",
  "我们根据公开的题库与方法说明检查重叠，并限制相关来源的总份额；无法确认的相关性仍是局限。当前 AA 指数占 30%；Arena 整体文本与创作专项共享原有 10% 真人偏好份额，各占 5%。两项有重叠投票，因此仍算同一个证据家族，不假装是两家独立评测。": "我们根据公开的题库与方法说明检查重叠，并限制相关来源的总份额；无法确认的相关性仍是局限。当前 AA 指数占 30%；Arena 整体文本与创作专项共享原有 10% 真人偏好份额，各占 5%。两项有重叠投票，因此仍算同一个证据家族，不假装是两家独立评测。",
  "价格或速度会影响排名吗？": "价格或速度会影响排名吗？",
  "都不会。价格只供你了解 API 的使用成本，统一按每百万 Token 展示，并保留厂商官方来源。它不代表订阅费用。": "都不会。价格只供你了解 API 的使用成本，统一按每百万 Token 展示，并保留厂商官方来源。它不代表订阅费用。",
