  "跨能力的综合测试与真人盲选。": "跨能力的综合测试与真人盲选。",
  "把多项当前评测放到同一套环境里复跑，得到一个综合能力分。价格只作参考，不进总分。": "把多项当前评测放到同一套环境里复跑，得到一个综合能力分。价格只作参考，不进总分。",
  "只取官方 Artificial Analysis Intelligence Index；接口中的性能与价格字段不计分。": "只取官方 Artificial Analysis Intelligence Index；接口中的性能与价格字段不计分。",
  "综合任务证据占 30%；已核对 v4.3 的 10 项底层评测，与现役专项没有重复计票。整项保留，不将聚合分冒充单项成绩。": "综合任务证据占 30%；已核对 v4.3 的 10 项底层评测，与现役专项没有重复计票。整项保留，不将聚合分冒充单项成绩。",
  "缺少 API key 时整张来源退出本轮，不补 50 分；严禁用网页抓取替代，展示时必须署名并保留指数版本。": "缺少 API key 时整张来源退出本轮，不补 50 分；严禁用网页抓取替代，展示时必须署名并保留指数版本。",
  "API 数据展示或分享须显著署名；再分发权与定制条款须另行取得并遵守 Terms of Use": "API 数据展示或分享须显著署名；再分发权与定制条款须另行取得并遵守 Terms of Use",
  "题库持续更换，答案可以自动核对。用来看模型换题之后还能不能站住。": "题库持续更换，答案可以自动核对。用来看模型换题之后还能不能站住。",
  "保留官方 Global Average 作整体参考；正式分数使用互不重复的专项任务。": "保留官方 Global Average 作整体参考；正式分数使用互不重复的专项任务。",
  "原始 Global Average 留作参考；正式票改用互不重复的专项任务。": "原始 Global Average 留作参考；正式票改用互不重复的专项任务。",
  "综合均分会稀释特定能力的变化；仅交叉参考，不重复计票。组织参与方 Abacus.AI 同时开发 Smaug 模型，其独家成绩需要其他独立来源补充。": "综合均分会稀释特定能力的变化；仅交叉参考，不重复计票。组织参与方 Abacus.AI 同时开发 Smaug 模型，其独家成绩需要其他独立来源补充。",
  "真人匿名两两比较回答，看大家更愿意读哪一个。补上选择题看不出的整体体验。": "真人匿名两两比较回答，看大家更愿意读哪一个。补上选择题看不出的整体体验。",
  "只取官方发布快照中的 Text Overall style-controlled 主榜，不抓取 arena.ai 实时页面。": "只取官方发布快照中的 Text Overall style-controlled 主榜，不抓取 arena.ai 实时页面。",
  "真人偏好预算 10% 分为整体 5% 和创作 5%；与 Arena 的编程和视觉评测仍共用证据家族。按官方成绩数据时间判断新旧。": "真人偏好预算 10% 分为整体 5% 和创作 5%；与 Arena 的编程和视觉评测仍共用证据家族。按官方成绩数据时间判断新旧。",
  "人类偏好受风格、用户结构和提示分布影响。整体与创作分类存在重叠投票，共享原有真人偏好预算，不视为两家独立评测机构。": "人类偏好受风格、用户结构和提示分布影响。整体与创作分类存在重叠投票，共享原有真人偏好预算，不视为两家独立评测机构。",
  "同样是真人盲选，比的是网页好不好用、能不能交付。": "同样是真人盲选，比的是网页好不好用、能不能交付。",
  "只取官方发布快照中的 WebDev 总榜，不抓取 arena.ai 实时页面；与 Text 共同构成一张 Arena 家族票。": "只取官方发布快照中的 WebDev 总榜，不抓取 arena.ai 实时页面；与 Text 共同构成一张 Arena 家族票。",
  "编程与设计预算中的 2.4%；在审美分类衡量网页作品偏好，不等同代码正确率。仍与 Arena 其他任务共用证据家族。": "编程与设计预算中的 2.4%；在审美分类衡量网页作品偏好，不等同代码正确率。仍与 Arena 其他任务共用证据家族。",
  "与 Text 存在偏好构念相关性。": "与 Text 存在偏好构念相关性。",
  "LiveBench · 语言与指令": "LiveBench · 语言与指令",
  "Language + IF 两项均分，各占 50%。": "Language + IF 两项均分，各占 50%。",
  "先分别计算 Language、IF 的分类成绩，再各占 50% 求平均，最后保留一位小数。两项均分与官网单独选择某一类的成绩不同。Language 衡量语言理解，IF 衡量指令与格式约束，不据此评价小说文笔。": "先分别计算 Language、IF 的分类成绩，再各占 50% 求平均，最后保留一位小数。两项均分与官网单独选择某一类的成绩不同。Language 衡量语言理解，IF 衡量指令与格式约束，不据此评价小说文笔。",
  "保留综合榜写作与表达预算中的 3%；不进入文学创作的写作分类。": "保留综合榜写作与表达预算中的 3%；不进入文学创作的写作分类。",
  "两项均分衡量组合表现，不能当成 Language 单项成绩。官方页面切换分类或是否包含微调模型时，分数与排序会随之变化。组织参与方 Abacus.AI 同时开发 Smaug 模型，其独家成绩需要其他独立来源补充。": "两项均分衡量组合表现，不能当成 Language 单项成绩。官方页面切换分类或是否包含微调模型时，分数与排序会随之变化。组织参与方 Abacus.AI 同时开发 Smaug 模型，其独家成绩需要其他独立来源补充。",
  "分项成绩由 LiveBench 发布，AIHOT 按上述两类等权汇总并排序。两项均分与 AIHOT 共识分使用不同尺度，不能直接相加。": "分项成绩由 LiveBench 发布，AIHOT 按上述两类等权汇总并排序。两项均分与 AIHOT 共识分使用不同尺度，不能直接相加。",
  "Language + IF 各占 50%，使用未舍入的分项成绩求平均。": "Language + IF 各占 50%，使用未舍入的分项成绩求平均。",
  "两项均分": "两项均分",
  "Arena 创作盲选": "Arena 创作盲选",
  "真人盲选故事、诗歌和其他创意表达，观察作品是否吸引读者。": "真人盲选故事、诗歌和其他创意表达，观察作品是否吸引读者。",
  "读取官方数据集 text_style_control 的 creative_writing 分类，采用风格控制后的 Bradley–Terry 分与置信区间；不借用整体文本或职业写作分类成绩。": "读取官方数据集 text_style_control 的 creative_writing 分类，采用风格控制后的 Bradley–Terry 分与置信区间；不借用整体文本或职业写作分类成绩。",
  "正式计分；从原有真人偏好 10% 中拆分 5%，整体文本保留 5%，总预算不增加。与其他 Arena 任务共用证据家族。": "正式计分；从原有真人偏好 10% 中拆分 5%，整体文本保留 5%，总预算不增加。与其他 Arena 任务共用证据家族。",
  "开放用户提示由分类器归类，并非全部为长篇小说或中文创作；投票包含个人偏好。与 Arena 整体文本及职业写作分类存在重叠，不能作为额外独立机构。": "开放用户提示由分类器归类，并非全部为长篇小说或中文创作；投票包含个人偏好。与 Arena 整体文本及职业写作分类存在重叠，不能作为额外独立机构。",
  "CC BY 4.0 · Arena 官方 Hugging Face leaderboard-dataset；保留署名、来源链接并说明聚合改动。": "CC BY 4.0 · Arena 官方 Hugging Face leaderboard-dataset；保留署名、来源链接并说明聚合改动。",
  "Design Arena · 视觉设计": "Design Arena · 视觉设计",
