  "仅比较 Models Arena 的基础模型；各设计任务共享家族预算，不把子标签当多个独立来源，也不与 codecategories 总分重复计票。": "仅比较 Models Arena 的基础模型；各设计任务共享家族预算，不把子标签当多个独立来源，也不与 codecategories 总分重复计票。",
  "观察中：正式 API 协议和展示条款已明确，待获批访问及逐项原始成绩核验。尚未采集、尚未计分。": "观察中：正式 API 协议和展示条款已明确，待获批访问及逐项原始成绩核验。尚未采集、尚未计分。",
  "公开网页不替代 API 授权；模型、Agent 和 Builder 不能混排。": "公开网页不替代 API 授权；模型、Agent 和 Builder 不能混排。",
  "正式 API 数据允许个人及商业展示，须署名和可见官网链接；API 需申请获批。": "正式 API 数据允许个人及商业展示，须署名和可见官网链接；API 需申请获批。",
  "EQ-Bench 4 · 情绪与人际理解": "EQ-Bench 4 · 情绪与人际理解",
