  "120 个模拟人物、16 轮角色扮演，三家模型裁判轮换盲评；只采用 Elo，行为风格 traits 不作越高越好的能力分。旧 v3 不重复计票。": "120 个模拟人物、16 轮角色扮演，三家模型裁判轮换盲评；只采用 Elo，行为风格 traits 不作越高越好的能力分。旧 v3 不重复计票。",
