  "600–800 词短篇、10 项创作要求；同提示、三家裁判、双向比较。采用 Thurstone 主分，BT 仅作诊断，不重复计票；多档位按固定规则选取。": "600–800 词短篇、10 项创作要求；同提示、三家裁判、双向比较。采用 Thurstone 主分，BT 仅作诊断，不重复计票；多档位按固定规则选取。",
