  "10 个真实脚本任务、多次生成、三家裁判；只比较相同任务、rubric、裁判和运行指纹。混合模型回退行须排除，不按每列最高成绩选配置。": "10 个真实脚本任务、多次生成、三家裁判；只比较相同任务、rubric、裁判和运行指纹。混合模型回退行须排除，不按每列最高成绩选配置。",
  "观察中：数据协议和当期覆盖较好，待确认成绩再展示边界并核验纯模型配置。": "观察中：数据协议和当期覆盖较好，待确认成绩再展示边界并核验纯模型配置。",
