  "统一 TubeLab Scriptwriter、12 个任务、6 项写作质量；三家模型裁判不评自己家，失败任务保留惩罚。成本和速度不进入能力。": "统一 TubeLab Scriptwriter、12 个任务、6 项写作质量；三家模型裁判不评自己家，失败任务保留惩罚。成本和速度不进入能力。",
