  "需要完整、已达到提示覆盖门槛的盲测分数；注册模型数量不等于有效上榜型号数。与其它 SVG 评测共用相关任务家族。": "需要完整、已达到提示覆盖门槛的盲测分数；注册模型数量不等于有效上榜型号数。与其它 SVG 评测共用相关任务家族。",
  "观察中：等待稳定原始成绩、可验证更新时间与再展示边界。": "观察中：等待稳定原始成绩、可验证更新时间与再展示边界。",
