  "只采用同一静态 SVG 任务的 Preference Elo；Alignment、Coherence 和 Overall 不重复计票。以官方数据集固定版本的公开成绩表为准，可追溯原始人类对战。": "只采用同一静态 SVG 任务的 Preference Elo；Alignment、Coherence 和 Overall 不重复计票。以官方数据集固定版本的公开成绩表为准，可追溯原始人类对战。",
  "观察中：官方数据与许可可用，但三条 DeepSeek 滚动别名缺少固定版本证据，整张成绩暂不采纳。等待评测方补充运行版本；没有削减现役来源预算。": "观察中：官方数据与许可可用，但三条 DeepSeek 滚动别名缺少固定版本证据，整张成绩暂不采纳。等待评测方补充运行版本；没有削减现役来源预算。",
  "SVG 绘图不能代表全部界面设计。公开原始数据不含模型版本、生成日期或 API fingerprint，无法判断滚动接口是否换版；不能用榜单更新日猜模型版本。": "SVG 绘图不能代表全部界面设计。公开原始数据不含模型版本、生成日期或 API fingerprint，无法判断滚动接口是否换版；不能用榜单更新日猜模型版本。",
