  "编程与设计预算中的 3.6%；固定受控系统与版本。": "编程与设计预算中的 3.6%；固定受控系统与版本。",
  "仍是模型＋mini-swe-agent 的系统表现；大版本变化必须隔离快照。": "仍是模型＋mini-swe-agent 的系统表现；大版本变化必须隔离快照。",
  "官方公开结构化结果；仅管理员私有观察，公开前复核许可": "官方公开结构化结果；仅管理员私有观察，公开前复核许可",
  "在真实游戏引擎里用 Lua 写出能跑起来的功能。分数由引擎执行判定，不用另一个模型打分。": "在真实游戏引擎里用 Lua 写出能跑起来的功能。分数由引擎执行判定，不用另一个模型打分。",
  "只取官方 main_board 的 L2 通过率；成本、速度、Held-out 和分类分不再次投票。同一基础模型按固定推理档位优先级选代表行，选择不看分数。": "只取官方 main_board 的 L2 通过率；成本、速度、Held-out 和分类分不再次投票。同一基础模型按固定推理档位优先级选代表行，选择不看分数。",
