  "单引擎、单语言，不能推广到其他技术栈；不同模型可能使用不同 agent 驱动；闭源 harness 不能逐题复算。": "单引擎、单语言，不能推广到其他技术栈；不同模型可能使用不同 agent 驱动；闭源 harness 不能逐题复算。",
