  "LiveBench · 编程综合": "LiveBench · 编程综合",
  "Coding + Agentic Coding 两项均分，各占 50%。": "Coding + Agentic Coding 两项均分，各占 50%。",
  "先分别计算 Coding、Agentic Coding 的分类成绩，再各占 50% 求平均，最后保留一位小数。两项均分与官网单独选择某一类的成绩不同。": "先分别计算 Coding、Agentic Coding 的分类成绩，再各占 50% 求平均，最后保留一位小数。两项均分与官网单独选择某一类的成绩不同。",
  "两项均分作为一份证据参与排名，各专项共用 LiveBench 证据家族；Global Average 仅供参考，不重复计票。": "两项均分作为一份证据参与排名，各专项共用 LiveBench 证据家族；Global Average 仅供参考，不重复计票。",
  "两项均分衡量组合表现，不能当成 Coding 单项成绩。官方页面切换分类或是否包含微调模型时，分数与排序会随之变化。组织参与方 Abacus.AI 同时开发 Smaug 模型，其独家成绩需要其他独立来源补充。": "两项均分衡量组合表现，不能当成 Coding 单项成绩。官方页面切换分类或是否包含微调模型时，分数与排序会随之变化。组织参与方 Abacus.AI 同时开发 Smaug 模型，其独家成绩需要其他独立来源补充。",
  "Coding + Agentic Coding 各占 50%，使用未舍入的分项成绩求平均。": "Coding + Agentic Coding 各占 50%，使用未舍入的分项成绩求平均。",
  "根据业务资料构建并测试能工作的客户服务代理。": "根据业务资料构建并测试能工作的客户服务代理。",
  "衡量代理开发与调试，和直接执行客户服务的 τ³-Banking 分开；固定开发工具、运行时长与验收环境，不能跨系统挑最高成绩。": "衡量代理开发与调试，和直接执行客户服务的 τ³-Banking 分开；固定开发工具、运行时长与验收环境，不能跨系统挑最高成绩。",
  "观察中：可补编程与业务系统开发，先完成原始成绩、许可和固定运行条件审查；不因新发布就自动计分。": "观察中：可补编程与业务系统开发，先完成原始成绩、许可和固定运行条件审查；不因新发布就自动计分。",
  "待确认榜单数据使用边界": "待确认榜单数据使用边界",
  "持续收集真实仓库问题，比较模型在多种编程语言中的软件修复能力。": "持续收集真实仓库问题，比较模型在多种编程语言中的软件修复能力。",
  "固定任务窗口、ReAct 环境和 text/tools 交互协议，采用多次运行的平均解决率与标准误；不把完整 Agent 产品与基础模型混为同一对象。": "固定任务窗口、ReAct 环境和 text/tools 交互协议，采用多次运行的平均解决率与标准误；不把完整 Agent 产品与基础模型混为同一对象。",
