  "重置卡正在发放": "Reset credits are being issued",
  "额度重置正在进行": "Quota reset in progress",
  "等待重置卡到账": "Awaiting reset credit delivery",
  "等待额度重置生效": "Awaiting quota reset",
  "已比预计晚 {value}，仍在等待确认": "{value} past the estimate; still awaiting confirmation",
  "距预计时段还有 {value}": "{value} until the estimated window",
  "Tibo {value} 表示正在进行": "Tibo reported it in progress at {value}",
  "· Tibo 已宣布": "· Announced by Tibo",
  "预计": "Estimated: ",
  "适用范围：": "Eligibility: ",
  "起因：": "Cause: ",
  "重置卡到账后由你自己决定何时使用。卡片余额以 Codex 内显示为准。": "Once delivered, you choose when to use your reset credit. Check its balance in Codex.",
  "剩余额度可以放心用，生效后会恢复满额。以你 Codex 里显示的用量为准。": "You can use the remaining quota; activation restores it in full. Check the usage shown in Codex.",
  "Codex 额度重置与重置卡发放：什么时候生效、给谁、Tibo 原话": "Codex quota resets and reset credits: when, who is eligible, and Tibo’s own words",
  "全部为北京时间 · UTC+8": "All times are Beijing time · UTC+8",
  "时间是怎么推算的？": "How are the times estimated?",
  "来源与规则": "Sources and rules",
  "有原话就按原话。": "Use explicit statements first. ",
  "Tibo 写了时间（如 “6pm PST”“next hour”“end of day”），按太平洋时间换算成北京时间，并多留一两个小时——他的确认帖通常比说的时间晚一点。只写了日期的，按他以往的习惯落在当天太平洋时间傍晚。": "If Tibo gives a time, such as “6pm PST”, “next hour” or “end of day”, we convert Pacific time to Beijing time and allow one or two extra hours: confirmations often arrive later. Date-only announcements use his usual Pacific evening window.",
  "没写时间就按习惯。": "Otherwise, use past patterns. ",
  "Tibo 多在太平洋时间 16:30–21:30 按下重置按钮，也就是北京时间第二天早上 07:30–12:30。": "Tibo usually triggers resets at 16:30–21:30 Pacific, or 07:30–12:30 Beijing the following morning.",
  "近 {value} 次确认中有 {value2} 次在这个时段。": "Recent confirmations: {value}; in this window: {value2}.",
  "推算只是参考，以 Tibo 的确认和你 Codex 里的用量为准。": "Estimates are for reference; Tibo’s confirmation and your Codex usage are authoritative.",
  "已生效、应已生效、等待中。": "Active, likely active, or pending. ",
  "Tibo 发帖确认才算“已生效”；预计时间过去几个小时仍没有确认帖，显示“应已生效”——他宣布过的重置以往都兑现了，只是常常不再发确认。重置卡与额度重置分开记录，发卡不代表额度已恢复。": "“Active” requires Tibo’s confirmation. Several hours after the estimated window without a post, we show “likely active”: announced resets have historically happened, often without follow-up confirmation. Credits and quota resets are tracked separately; a credit does not mean the quota has reset.",
  "持续跟踪 Tibo 的公开帖子。": "Continuously follow Tibo’s public posts. ",
  "平时每 5 分钟检查一次，Tibo 确认故障或宣布重置后改为每 3 分钟。只有明确的重置或发卡消息才会推送飞书群。个人额度和重置卡余额请在 Codex 内查看。": "Checks run every 5 minutes, switching to 3 minutes after an outage or reset announcement. Only explicit reset or credit announcements are sent to the Feishu group. Check personal quotas and credit balances in Codex.",
