  "综合名次，有多稳定？": "How stable is the overall rank?",
  "依次移除一项评测或一家机构、调整单项权重与误差处理，观察排名怎样变化。": "Remove one evaluation or organization at a time, vary weights and uncertainty handling, and observe rank changes.",
  "重新检查资格后的名次": "Rank after rechecking eligibility",
