  "保持原候选不变时为": "With the original candidates fixed: ",
  "名。这个范围不是置信区间，也不包含从未公开的成绩。": ". This range is not a confidence interval and excludes unpublished results.",
  "持平": "Tie",
  "查看与附近模型的共同证据": "Compare shared evidence with nearby models",
  "净支持只看双方共同参加的评测。全局排序还需处理其他模型间的冲突，因此非相邻名次可能与单独比较不同。": "Net support uses only evaluations both models entered. Global ranking also resolves conflicts among other models, so nonadjacent positions may differ from a direct comparison.",
  "共同证据支持本模型": "Shared evidence favors this model",
  "共同证据支持对方": "Shared evidence favors the other model",
