  "缓存": "Cache ",
  "原价": "List price ",
  "厂商官方价格": "Official vendor prices",
  "尚未核到厂商官网价格": "Official prices not verified yet",
  "待核验": "Unverified",
  "每一项成绩，都有来处。": "Every score has a source.",
  "下面是该模型的公开汇总成绩。展开可查看运行配置与采用方式。": "Published aggregate scores for this model. Expand for configurations and how each result is used.",
  "项": "items",
  "没有测到的计分评测": "Scoring evaluations without results",
  "这些评测没有公开该模型的成绩，缺测不记零分。": "These evaluations have not published this model’s results. Missing results do not count as zero.",
  "还有一些未知": "Some things remain unknown",
  "缺失的评测不会记成零分。模型的名次会随新证据变化，分数相近时不宜过度解读细小差距。": "Missing evaluations are not zero. Rankings change with new evidence; avoid overinterpreting small gaps between similar scores.",
  "了解计算方法 →": "Read the methodology →",
  "共识指数计算方法": "Consensus index methodology",
  "查看 {value} 模型榜如何核验公开成绩、比较共同参评结果、处理缺失证据，并确定排名和 0—100 共识指数。": "How {value} verifies public results, compares shared evaluations, handles missing evidence and determines ranks and the 0–100 consensus index.",
  "本页内容": "On this page",
  "当前方法": "Current method",
  "方法版本": "Method version",
  "本轮计算": "Current run",
  "继续看": "Keep exploring",
  "每一份评测证据": "Every evaluation source",
  "返回模型榜": "Back to model leaderboard",
  "综合多家公开评测，了解排名背后的证据与方法。": "Public evaluations combined: understand the evidence and method behind the ranking.",
  "共同的证据，清楚的顺序。": "Shared evidence, a clear order.",
  "综合多家公开评测，在完整排名中尽量减少与已知成绩的冲突。综合榜和四类榜单都最多展示前 30 名。": "We combine public evaluations to minimize conflicts with known results in a complete ranking. The overall and four category boards each show up to 30 models.",
  "共识指数把支持原排名的证据差异换算为 0—100，方便比较，不是正确率或能力差距的百分比。支持接近时可以同分，名次仍由完整证据决定。": "The index maps evidence differences supporting the ranking to 0–100. It is not accuracy or a percentage capability gap. Similar support can produce equal scores; the full evidence still determines rank.",
  "综合测试、真人盲选、专项评测，一起看。": "Broad tests, human preferences and specialist evaluations together.",
  "综合评测占 30%，真人盲选占 10%，各项专项评测合计占 60%。新增评测先核对公开说明中的重叠关系，再从对应份额中分配；缺失份额不转给其他评测。": "Broad evaluations receive 30%, human preferences 10%, and specialist evaluations 60%. New sources are checked for overlap before receiving a share; missing shares are not reassigned.",
  "证据预算分配": "Evidence budget allocation",
  "编程、推理、知识、专业办公分别寻找真实评测，分类分独立计算。视觉理解与多语言证据继续保留在综合榜；调整分类名称不会增加同一份成绩的投票权。综合分不等于分类分的算术平均。分类通常至少有两项有效评测、五个可比较型号才展示。知识目前由 Epoch 的两套评测支持，并明确说明同机构的局限。创作偏好、网页开发等证据继续用于综合榜，首版不单设审美和写作榜。": "Coding, reasoning, knowledge and professional work use real measurements and separate category scores. Vision and multilingual evidence remain in the overall board; renaming categories adds no votes. Overall scores are not category averages. Categories generally need two valid evaluations and five comparable models. Knowledge currently uses two Epoch evaluations, with the single-organization limitation stated. Creative preferences and web development remain in the overall board; separate aesthetics and writing boards are not included in this first version.",
  "你可能还想知道": "You may also want to know",
  "查看计算细节与当前版本": "Calculation details and current version",
  "方法版本：": "Method version: ",
  "。采用加权不完整 Kemeny 排序。每对共同参评模型汇总净支持 M；目标是最小化所有被排反的净支持之和。整数优化返回最优状态和目标上下界，只有完整通过验证的结果才用于正式发布。": ". We use weighted incomplete Kemeny ranking. Shared model pairs aggregate net support M; the objective minimizes support placed in reverse order. Integer optimization returns optimal status and bounds. Only fully validated results are published.",
  "双方有明确标准误时，净支持取 2Φ(分差 / 合成标准误) − 1，默认零协方差；其他比较只取原始领先方向。未知误差并非零误差，小分差按序数处理仍是局限。票权针对潜在模型对，覆盖型号多的来源会使用更多比较位置，不能把名义预算解读为最终名次的精确贡献率。": "With known standard errors for both results, net support is 2Φ(score difference / combined standard error) − 1, assuming zero covariance. Other comparisons use the raw lead direction. Unknown error is not zero error; ordinal treatment of small gaps remains a limitation. Weights apply to potential model pairs, so broader sources occupy more comparison positions. Nominal budgets are not exact contributions to final ranks.",
  "展示指数保留原排序：逐对反转相邻模型的先后，允许其余模型重排，计算最少增加的逆向净支持。沿原排名累加这些非负支持差，再相对固定参照组用 sigmoid 映射到 0—100。替代顺序同样最优时保留零间距，显示保留一位小数，不人为设置最低分差。指数不参与反向排序；入榜集合、参照型号与证据变化仍会影响指数，分差不等于真实能力距离。同代价求解固定型号 ID 次序；整数优化使用 HiGHS 求解器（highs 1.15.3），误差换算的正态分布函数与 SciPy norm.cdf 采用同一算法；来源、协议、参评资格和每轮计算输入均保存版本。未连接到共同证据网络时不发布跨分量的假精确顺序。": "The index preserves the order. Reverse each adjacent pair, allow others to reorder, and measure the minimum extra opposing support. Accumulate these nonnegative gaps along the ranking, then map them to 0–100 with a sigmoid relative to a fixed reference group. Equally optimal alternatives retain zero gaps; display uses one decimal with no artificial minimum gap. The index does not reorder models. Membership, references and evidence affect it; score gaps are not true capability distances. Equal-cost solutions use fixed model-ID order. Integer optimization uses HiGHS (highs 1.15.3); the normal-distribution conversion uses the same algorithm as SciPy norm.cdf. Sources, protocols, eligibility and run inputs are versioned. Disconnected evidence components are not given a falsely precise shared order.",
  "固定参照型号：": "Fixed reference models: ",
  "。参照组用于指数尺度，不指定任何厂商应排第几；不同分类的指数不直接比较。": ". The reference group sets the scale without prescribing vendor positions. Category indices are not directly comparable.",
