  "“观察中”表示仍在核对数据、运行条件或使用边界，不参与综合榜和分类榜。同一评测的重复抓取和展示切片不会增加票权；不同评测之间的题库重叠仍需持续核对。": "“Observing” means data, conditions or usage limits are still being checked; the source does not affect any ranking. Repeated snapshots and slices add no voting weight. Overlap across evaluations remains under review.",
