  "“观察中”表示仍在核对数据、运行条件或使用边界，不参与综合榜和分类榜。同一评测的重复抓取和展示切片不会增加票权；不同评测之间的题库重叠仍需持续核对。": "«Наблюдение» означает проверку данных, условий или границ использования; источник не влияет на рейтинги. Повторные снимки и срезы не добавляют веса. Пересечение оценок продолжаем проверять.",
