  "{count} 次发重置卡": {"one": "{count} выдача кредита сброса", "few": "{count} выдачи кредитов сброса", "many": "{count} выдач кредитов сброса", "other": "{count} выдач кредитов сброса"},
  "{count} 次等待生效": {"one": "{count} ожидаемое применение", "few": "{count} ожидаемых применения", "many": "{count} ожидаемых применений", "other": "{count} ожидаемых применений"},
  "今天": "Сегодня",
  "已选择 {date}，{count} 条记录。": {"one": "Выбрано {date}, {count} запись.", "few": "Выбрано {date}, {count} записи.", "many": "Выбрано {date}, {count} записей.", "other": "Выбрано {date}, {count} записей."},
  "额度重置": "Сброс квоты",
