  "这件事共有 {count} 条相关原帖{earliest}。": {"one": "Связанных постов: {count}{earliest}.", "few": "Связанных постов: {count}{earliest}.", "many": "Связанных постов: {count}{earliest}.", "other": "Связанных постов: {count}{earliest}."},
