  "Tibo 只给了日期，按他以往的习惯落在当天太平洋时间傍晚。": "Tibo назвал только дату; используем обычный тихоокеанский вечер.",
  "按原帖时间换算成北京时间，并预留一两个小时：他的确认帖通常比说的时间晚一点。": "Переводим время в пекинское и добавляем один-два часа; подтверждения часто запаздывают.",
